#!/bin/bash

set -e

DEFINE_SERVER_ADDR="localhost"
DEFINE_SERVER_PORT=12346
DEFINE_HELLO_PACKET="2000010208864011061834612f01300000000000000006025e23b7685163c3fa"
DEFINE_CFG_PACKET=""
# DEFINE_CFG_PACKET=""
DEFINE_SYNC_PACKET="0d000406020d280a6900000000" # 
DEFINE_UNK_PACKET="88000330313030343236433131384136374543303034364645363734324239433836303432343630413030303030303742303031463134464337354346363930303030463830453030353330303030314430303442303033443030464130303134303043344439303030303030303030303030303030303030303731413030314230303143303000"
DEFINE_KEEPALIVE_PACKET="aa"

DEFINE_EMULATOR_LOG="EMULATOR"
DEFINE_SERVER_LOG="TCPSERV"

log() {
    local type=$1
    local msg=$2

    echo "$(date '+%b %d %H:%M:%S') admrc-emulator[$$]: $type: $msg"
}

send_pack() {
    local packet_hex=$1
    local desc=$2

    log "EMULATOR" "Send packet | $desc"

    printf "%s" "$packet_hex" | xxd -r -p >&3
}

connect_server() {
    log "EMULATOR" "Connecting to $DEFINE_SERVER_ADDR:$DEFINE_SERVER_PORT..."
    exec 3<>/dev/tcp/$DEFINE_SERVER_ADDR/$DEFINE_SERVER_PORT
    send_pack "$DEFINE_HELLO_PACKET" "Hello packet"
}

disconnect_server() {
    log "EMULATOR" "Disconnecting from server"
    exec 3>&-
    exec 3<&-
}

dump_raw() {
    if read -r -u 3 -t 0.5 -n 1 first; then
        {
            printf "%s" "$first"
            dd bs=1 count=1024 <&3 2>/dev/null
        } | xxd -p
        echo
    fi
}

read_packet() {
    size_bytes=$(dd bs=1 count=2 <&3 2>/dev/null | xxd -p -c2 | tr -d '\n')
    [[ -z "$size_bytes" ]] && return 1

    size=$((0x$(echo "$size_bytes" | sed 's/\(..\)\(..\)/\2\1/')))
    data_len=$((size - 2))

    rest=""
    if (( data_len > 0 )); then
        rest=$(dd bs=1 count=$data_len <&3 2>/dev/null | xxd -p -c256 | tr -d '\n')
    fi

    echo "$size_bytes$rest"
}

handle_command() {
    local type_hex=$1
    local cmd_type_hex=$2
    local cmd_data_hex=$3

    local cmd_data=""
    if [[ -n "$cmd_data_hex" ]]; then
        cmd_data=$(echo "$cmd_data_hex" | xxd -r -p 2>/dev/null || true)
    fi

    case "$cmd_type_hex" in
        01) # строковая команда
            log "EMULATOR" "Received string command -> '$cmd_data'"

            cmd_data_upper=$(echo "$cmd_data" | tr '[:lower:]' '[:upper:]')

            case "$cmd_data_upper" in
                "BLESENSORINFO")
                    response=""
                    send_pack "$response" "Response to BLESENSORINFO"
                    ;;
                "COM0")
                    response="88000330313030343236433131384136374543303034364645363734324239433836303432343630413030303030303742303031463134464337354346363930303030463830453030353330303030314430303442303033443030464130303134303043344439303030303030303030303030303030303030303731413030314230303143303000"
                    # 88000330313030343236433131384136374543303034364645363734324239433836303432343630413030303030303742303031463134464337354346363930303030463830453030353330303030314430303442303033443030464130303134303043344439303030303030303030303030303030303030303731413030314230303143303000
                    send_pack "$response" "Response to COM0"
                    ;;
                "ADM20INFO")
                    response="1e000341444d3230494e464f3a20303b20303b20302c302c302c302c3000"
                    send_pack "$response" "Response to ADM20INFO"
                    ;;
                "FUELINFO")
                    response="6500034655454c494e464f3a205b302c424c455d3a204535463241393532374231443b2044543a303b204c4d543a303b20523a303b205b312c3438355d3a2031353b204c3a303b20543a303b205b322c3438355d3a2032353b204c3a303b20543a303b2000"
                    send_pack "$response" "Response to FUELINFO"
                    ;;
                "WHO")
                    response="1c0003312c61646d7035302c3231352c61646d7035302c362c3100"
                    send_pack "$response" "Response to WHO"
                    ;;
                "STATUS")
                    response="78000349443d3120536f66743d30783036204750533d31393637312054696d653d31383a34323a30302030362e31312e32352056616c3d31204c61743d302e3030303030204c6f6e3d302e303030303020563d3020536174436e743d302b3020537461743d3078363062382c20496e5f616c61726d3d3000"
                    send_pack "$response" "Response to STATUS"
                    ;;
                *)
                    log "EMULATOR" "Unknown string command: '$cmd_data'"
                    response="130003556e6b6e6f776e20636f6d6d616e6400"
                    send_pack "$response" "Response to unknown string command"
                    ;;
            esac
            ;;
        02) # запрос синхронизации
            send_pack "$DEFINE_SYNC_PACKET" "Sync response"
            ;;
        03) # запрос конфигурации
            log "EMULATOR" "Configuration request received"
            send_pack "$DEFINE_CFG_PACKET" "Config response"
            ;;
        *)
            log "EMULATOR" "Unknown CMD_TYPE: $cmd_type_hex"
            ;;
    esac
}

send_periodic() {
    local start_time=$(date +%s)
    local last_keepalive=$start_time
    local last_sync=$start_time
    local last_hello=$start_time

    while true; do
        now=$(date +%s)

        # Keep-alive каждые 3 минуты
        if (( now - last_keepalive >= 180 )); then
            send_pack "$DEFINE_KEEPALIVE_PACKET" "Keep-alive 0xAA"
            last_keepalive=$now
        fi

        # Sync каждые 5 минут
        if (( now - last_sync >= 10 )); then
            send_pack "$DEFINE_SYNC_PACKET" "Sync packet"
            last_sync=$now
        fi

        # if (( now - last_hello >= 30 )); then
        #     send_pack "$DEFINE_HELLO_PACKET" "Periodic Hello packet"
        #     last_hello=$now
        # fi

        sleep 1
    done
}

cat << 'EOF'

  ___           __   __   _____           __
 / _ \    /\   |  \ /  | |  ___)          \ \
| |_| |  /  \  |   v   | | |_   _   _ _   _\ \   __  _____ ___   ___
|  _  | / /\ \ | |\_/| | |  _) | | | | | | |> \ /  \/ (   ) _ \ / _ \
| | |/ /__\ \| |   | | | |___| |_| | |_| / ^ ( ()  < | ( (_) ) |_) )
|_| |_/________\_|   |_| |_____) ._,_|\___/_/ \_\__/\_\ \_)___/|  __/
                               | |                             | |
                               |_|                             |_|

EOF

while true; do
    connect_server

    send_periodic &

    while true; do
        if raw=$(read_packet); then
            log "$DEFINE_EMULATOR_LOG" "Received -> '$raw'"

            type_hex=${raw:4:2}
            cmd_type_hex=${raw:6:2}
            payload_hex=${raw:8}

            handle_command "$type_hex" "$cmd_type_hex" "$payload_hex"
        fi
    done
done
